children.definitions:
def Powerful (m : Nat) : Prop := ∀ (p : Nat), p ∣ m → p ^ 2 ∣ m

def EventuallyNotPowerful (f : Nat → Nat) : Prop :=
  ∃ (N : Nat), ∀ (n : Nat), N ≤ n → ¬ Powerful (f n)

def InfinitelyOftenPowerful (f : Nat → Nat) : Prop :=
  ∀ (N : Nat), ∃ (n : Nat), N ≤ n ∧ Powerful (f n)

